  "area": "Gantt",
  "ko": "{a} — 유닛 또는 스테이션을 고른 뒤 행과 날짜를 클릭 · {b} — 정확한 날짜 입력 · {c} — 장비 한 대의 전체 순서를 다른 유닛에 적용",
