 "Drafts are saved automatically as you type, even if you close the tab by mistake. They aren't visible to anyone else until you report them.": {
  "area": "Dialogs",
  "ko": "입력하는 동안 자동으로 임시 저장되며, 실수로 탭을 닫아도 유지됩니다. 보고하기 전까지는 다른 사람에게 보이지 않습니다.",
  "ar": "تُحفظ المسودات تلقائيًا أثناء الكتابة، حتى لو أغلقت التبويب بالخطأ. لا يراها أحد غيرك حتى تبلغ عنها."
 },
 "Drafts are saved on this device as you type, even if you close the tab by mistake. Nobody else can see them until you report them.": {
  "area": "Dialogs",
  "ko": "입력하는 동안 이 기기에 임시 저장되며, 실수로 탭을 닫아도 유지됩니다. 보고하기 전까지는 다른 사람이 볼 수 없습니다.",
  "ar": "تُحفظ المسودات على هذا الجهاز أثناء الكتابة، حتى لو أغلقت التبويب بالخطأ. لا يراها أحد غيرك حتى تبلغ عنها."
 },
 "Drag blocks and spaces to reorder the template. Hover between cards to insert a Process Block or Space.": {
  "area": "Dialogs",
  "ko": "블록과 간격을 드래그해 템플릿 순서를 바꾸세요. 카드 사이에 마우스를 올리면 공정 블록이나 간격을 삽입할 수 있습니다.",
  "ar": "اسحب البلوكات والفواصل لإعادة ترتيب القالب. مرّر المؤشر بين البطاقات لإدراج بلوك عملية أو فاصل."
 },
