 "The delay each station is adding to unit finishes right now (delays already absorbed by the plan are left out). <b>Show in Plan Table</b> filters the table to that station so you can record actual dates or add a delay reason.": {
  "area": "Dialogs",
  "ko": "각 스테이션이 현재 유닛 완료에 더하고 있는 지연입니다 (계획에 이미 반영된 지연은 제외). <b>계획 표에서 보기</b>를 누르면 표가 해당 스테이션으로 필터링되어 실제 날짜를 기록하거나 지연 사유를 추가할 수 있습니다.",
  "ar": "التأخير الذي تضيفه كل محطة إلى انتهاء الوحدات الآن (التأخيرات التي استوعبتها الخطة مستبعدة). <b>عرض في جدول الخطة</b> يصفّي الجدول لتلك المحطة لتتمكّن من تسجيل التواريخ الفعلية أو إضافة سبب التأخير."
 },
